    # Daftar dependensi Chromium Playwright + pustaka transisinya.
    "libasound2", "libasound2t64", "libatk-bridge2.0-0", "libatk-bridge2.0-0t64",
    "libatk1.0-0", "libatk1.0-0t64", "libatspi2.0-0", "libatspi2.0-0t64",
