# ---------------------------------------------------------------------------
# Adapter laporan: satu-satunya pemindai kerentanan adalah SatriaBaruScanner.
# Mesin probe tambahan 31-kategori telah dihapus dari jalur eksekusi.
def _legacy_scan_to_engine_lab_report(scan_report: dict[str, Any],
                                      discovered_urls: list[str] | None = None) -> dict[str, Any]:
    discovered_urls = list(dict.fromkeys(str(u) for u in (discovered_urls or []) if u))[:73]
    source_labs = scan_report.get("labs") if isinstance(scan_report, dict) else []
    source_labs = source_labs if isinstance(source_labs, list) else []
    ranges = globals().get("_LAB_TYPE_RANGES", [])

    def category_for(item: dict) -> str:
        match = re.search(r"-(\d{2})$", str(item.get("id") or ""))
        number = int(match.group(1)) if match else -1
        for low, high, title in ranges:
            if low <= number <= high:
                return title
        return "Pemeriksaan SATRIA"

    per_lab: list[dict[str, Any]] = []
    for raw in source_labs:
        if not isinstance(raw, dict):
            continue
        category_title = category_for(raw)
        status = "detected" if raw.get("status") == "confirmed" else "not_verified"
        per_lab.append({
            "id": raw.get("id", ""),
            "title": raw.get("title", ""),
            "level": str(raw.get("severity") or "info").lower(),
            "category": category_title,
            "category_title": category_title,
            "status": status,
            "evidence": str(raw.get("evidence") or "Belum ada bukti yang memenuhi kriteria konfirmasi."),
            "location": raw.get("location", "-"),
            "method": raw.get("method", ""),
        })

    detected = [x for x in per_lab if x["status"] == "detected"]
    not_verified = [x for x in per_lab if x["status"] == "not_verified"]
    groups: dict[str, list[dict[str, Any]]] = {}
    for item in per_lab:
        groups.setdefault(item["category_title"], []).append(item)
    category_summary = []
    for title, items in groups.items():
        category_summary.append({
            "category": title, "title": title, "total": len(items),
            "detected": sum(x["status"] == "detected" for x in items),
            "candidate": 0, "not_verified": sum(x["status"] == "not_verified" for x in items),
            "not_applicable": 0,
        })

    source_stats = scan_report.get("scan_stats") if isinstance(scan_report, dict) else {}
    source_stats = dict(source_stats) if isinstance(source_stats, dict) else {}
    errors = list(scan_report.get("errors") or []) if isinstance(scan_report, dict) else []
    source_stats.update({
        "pages_discovered": len(discovered_urls),
        "pages_scanned": 1 if scan_report else 0,
        "discovery_limit": 73,
        "passive_runs": 0, "active_runs": 0,
        "errors": list(dict.fromkeys(errors + list(source_stats.get("errors") or []))),
        "scanner": "SatriaBaruScanner (227 criteria)",
        "auxiliary_31_category_scanner": "removed",
    })
    summary = scan_report.get("summary") if isinstance(scan_report, dict) else {}
    return {
        "target": scan_report.get("target", "") if isinstance(scan_report, dict) else "",
        "labs_total": len(per_lab), "pages_discovered": len(discovered_urls),
        "pages_scanned": 1 if scan_report else 0,
        "detected": detected, "detected_lab_count": len(detected),
        "candidates": [], "not_verified": not_verified, "not_applicable": [],
        "per_lab": per_lab, "category_summary": category_summary,
        "findings": list(scan_report.get("findings") or []) if isinstance(scan_report, dict) else [],
        "candidate_findings": [], "stats": source_stats,
        "discovered_pages": discovered_urls, "scanned_pages": [scan_report.get("target", "")] if scan_report else [],
        "summary": summary if isinstance(summary, dict) else {},
    }

def render_lab_report(report: dict, max_rows: int = 40) -> str:
    lines = [
        f"## Pemindaian Kerentanan Terstruktur — {report['target']}",
        "",
        f"- Total pemeriksaan dalam katalog: **{report['labs_total']}**",
        f"- Halaman yang dianalisis pada origin yang sama: **{report.get('pages_discovered', 1)}**",
        f"- Terkonfirmasi: **{report.get('detected_lab_count', len(report['detected']))} pemeriksaan** "
        f"(dalam {len(report['detected'])} kelompok ciri)",
        f"- Kandidat (butuh verifikasi): **{len(report['candidates'])}**",
        f"- Tidak relevan untuk target ini: **{len(report['not_applicable'])}**",
        f"- Belum terbukti: **{len(report['not_verified'])}**",
        "",
    ]
    if report["detected"]:
        lines.append("### Pemeriksaan terkonfirmasi (bukti cocok)")
        lines.append("")
        lines.append("| Pemeriksaan | Level | Bukti |")
        lines.append("|---|---|---|")
        for r in report["detected"][:max_rows]:
            label = r["title"].replace("|", "/")
            lines.append(f"| {label} | {r['level']} | {r['evidence'][:200].replace('|', '/')} |")
        lines.append("")
    if report["candidates"]:
        lines.append("### Kandidat (perlu satu langkah verifikasi)")
        lines.append("")
        lines.append("| Pemeriksaan | Level | Indikasi |")
        lines.append("|---|---|---|")
        for r in report["candidates"][:max_rows]:
            lines.append(f"| {r['title']} | {r['level']} | {r['evidence'][:160]} |")
        lines.append("")
    lines.append("### Ringkasan per kategori")
    lines.append("")
    lines.append("| Kategori | Pemeriksaan | Terkonfirmasi | Kandidat | Tidak relevan |")
    lines.append("|---|---|---|---|---|")
    for c in report["category_summary"]:
        lines.append(f"| {c['title']} | {c['total']} | {c['detected']} | {c['candidate']} | "
                     f"{c['not_applicable']} |")
    return "\n".join(lines)


"""Orkestrator akhir: run_pipeline() dan render_pdf() — API publik dipertahankan."""

import html as html_lib
import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Optional


# ══════════════════════════════════════════════════════════════════════════════
# PIPELINE
# ══════════════════════════════════════════════════════════════════════════════
def _resolve_inputs(scrape_data: Optional[dict] = None, url: Optional[str] = None,
                    html: Optional[str] = None) -> tuple[str, str]:
    target_url = normalize_url(url) if url else ""
    page_html = html or ""
    if scrape_data:
        paths = persist_scrape_artifacts(scrape_data)
        page_html, scraped_url = load_scrape_html(paths["html"])
        if not target_url:
            target_url = scraped_url
    if not page_html:
        raise RuntimeError("Tidak ada HTML untuk dianalisis. Berikan scrape_data atau html.")
    if not target_url or target_url == "unknown":
        raise RuntimeError("URL target tidak diketahui; analisis lab butuh URL.")
    return target_url, page_html


def _run_pipeline_impl(scrape_data: Optional[dict] = None, *, url: Optional[str] = None,
                       html: Optional[str] = None, authorized: Optional[bool] = None,
                       http_result: Optional[dict] = None) -> dict[str, Any]:
    """Jalankan seluruh pipeline SATRIA untuk SATU target.

    Parameter
    ---------
    scrape_data : dict hasil scraper (cara lama, tetap didukung)
    url, html   : jalur alternatif tanpa scraper
    authorized  : izin probe aktif; default mengikuti gate global
    http_result : hasil analyze_http_security bila sudah ada (menghindari request ulang)
    """
    started = datetime.now(timezone.utc)
    target_url, page_html = _resolve_inputs(scrape_data, url, html)
    if authorized is None:
        authorized = active_probe_enabled()

    _scan_begin(force=True)
    print(f"\n[*] Target: {target_url}", flush=True)
    print(f"[*] Mode  : {'PASIF + AKTIF (diizinkan)' if authorized else 'PASIF saja'}", flush=True)

    # ── Section 1: HTTP ──────────────────────────────────────────────────────
    print("[1/10] Memeriksa keamanan HTTP (header, cookie, CORS, redirect) ...", flush=True)
    if http_result is None:
        try:
            http_result = analyze_http_security(target_url)
        except Exception as exc:
            http_result = {"errors": [str(exc)], "headers": {}, "cookies": [],
                           "findings": [], "status_code": None}
    http_findings = list(http_result.get("findings") or [])

    # ── Section 2: temuan kode deterministik ─────────────────────────────────
    print("[2/10] Menganalisis temuan kode deterministik (SRI, skrip pihak ketiga) ...", flush=True)
    code_findings = detect_code_findings_deterministic(page_html, target_url)

    # ── Section 3: discovery 73 URL (GET-only), lalu scan 1 URL utama ─────────
    print("[3/10] Discovery same-origin maksimal 73 URL (tanpa probe pada subhalaman) ...", flush=True)
    discovery_urls: list[str] = [target_url]
    try:
        root_context = build_target_context(target_url, page_html, http_result or {}, authorized=bool(authorized))
        discovered_contexts = _discover_same_origin_contexts(root_context, max_pages=73)
        discovery_urls = [str(getattr(item, "url", "")) for item in discovered_contexts if getattr(item, "url", "")]
    except Exception as discovery_exc:
        print(f"[WARN] Discovery gagal; scan URL utama tetap dilanjutkan: {type(discovery_exc).__name__}: {discovery_exc}", flush=True)
    print("[4/10] Memindai kerentanan hanya pada URL utama ...", flush=True)
    primary_scan = scan_target(
        target_url, authorized=bool(authorized), allow_private=False, max_pages=1,
        rendered_html=None, render_html=None,
    )
    lab_report = _legacy_scan_to_engine_lab_report(primary_scan, discovery_urls)
    lab_findings = list(primary_scan.get("findings") or [])

    # ── Section 4: teknologi & CVE (opsional) ────────────────────────────────
    print("[5/10] Mengidentifikasi teknologi dan mencari CVE ...", flush=True)
    technologies = extract_tech_versions_deterministic(
        page_html,
        headers=(http_result or {}).get("headers") or {},
        cookies=(http_result or {}).get("cookies") or [],
    )
    cves: list[dict] = []
    if RUN_NVD or RUN_CENSYS:
        for tech_idx, tech in enumerate(technologies[:10], start=1):
            _emit_progress(tech_idx, min(10, len(technologies)),
                           f"Lookup CVE: {tech['name']} {tech['version']}")
            if _scan_stop(f"CVE {tech['name']}"):
                break
            try:
                cves.extend(search_nvd_verified(tech["name"], tech["version"]))
                cves.extend(search_osv_verified(tech["name"], tech["version"]))
            except Exception as exc:
                print(f"      [CVE] dilewati untuk {tech['name']}: {exc}")

    # ── Gabung, dedup, ringkas ───────────────────────────────────────────────
    print("[6/10] Menggabungkan dan deduplikasi temuan ...", flush=True)
    combined = dedup_and_merge_findings(http_findings + code_findings + lab_findings)
    summary = summarize(combined)

    result: dict[str, Any] = {
        "target": target_url,
        "generated_at": started.isoformat(),
        "mode": "active" if authorized else "passive",
        "findings": combined,
        "summary": summary,
        "sections": {
            "http": http_findings,
            "code": code_findings,
            "portswigger": lab_findings,
        },
        "portswigger": lab_report,
        "technologies": technologies,
        "cves": cves,
        "http": {
            "status_code": http_result.get("status_code"),
            "final_url": http_result.get("final_url"),
            "headers": http_result.get("headers"),
            "errors": http_result.get("errors"),
        },
        "errors": list(primary_scan.get("errors") or []),
    }

    print("[7/10] Menyimpan temuan ...", flush=True)
    try:
        ARTIFACTS_DIR.mkdir(parents=True, exist_ok=True)
        Path(FINDINGS_PATH).write_text(json.dumps(result, indent=2, ensure_ascii=False),
                                       encoding="utf-8")
        print(f"[*] Temuan disimpan: {FINDINGS_PATH}", flush=True)
    except Exception as exc:
        print(f"[!] Gagal menyimpan {FINDINGS_PATH}: {exc}", flush=True)

    print("[8/10] Pemindaian selesai; laporan PDF dibuat setelah fungsi ini ...", flush=True)
    print(f"[*] Selesai: {summary['total']} temuan "
          f"({', '.join(f'{k}={v}' for k, v in summary['by_severity'].items() if v)})")
    return result


