    if cves:
        cve_rows = []
        for c in cves[:40]:
            if isinstance(c, dict):
                cid = str(c.get("id") or c.get("cve_id") or c.get("cve") or "-")
                sev = str(c.get("severity") or c.get("cvss") or "-")
